function optionsFor(type,record={}){let arr=type==='complex'?data.complexes:type==='property'?data.properties:type==='parkingSpace'?data.parkingSpaces:type==='tenant'?data.tenants:data.contracts;if(type==='contract'&&editing?.type==='parkingAssignment'){const space=parking(record.parkingSpaceId);if(space)arr=arr.filter(c=>prop(c.propertyId)?.complexId===space.complexId);}return arr.map(x=>`<option value="${esc(x.id)}">${esc(type==='complex'?x.name:type==='property'?propertyLabel(x):type==='parkingSpace'?(complex(x.complexId)?.name||'Complejo')+' · '+x.code:type==='tenant'?x.name:propName(x)+' · '+tenantName(x))}</option>`).join('');}
function showForm(type,id=null,opts={}){const s=schema[type];if(!s)return;if(type==='property'&&!data.complexes.length){toast('Cargá un complejo antes de registrar unidades.');return;}if(type==='parking'&&!data.complexes.length){toast('Cargá un complejo antes de registrar cocheras.');return;}if(type==='contract'&&(!data.properties.length||!data.tenants.length)){toast('Cargá una unidad y un inquilino antes del contrato.');return;}if(type==='payment'&&!data.contracts.length){toast('Cargá un contrato antes de registrar pagos.');return;}if(type==='parkingAssignment'&&(!data.parkingSpaces.length||!data.contracts.length)){toast('Cargá una cochera y un contrato antes de asignar.');return;}
  editing={type,id,collect:!!opts.collect};const source=id?data[s.collection].find(x=>x.id===id):{};if(id&&!source)return;const record={...source};
  if(type==='parkingAssignment'&&!id){record.parkingSpaceId=opts.parkingSpaceId||data.parkingSpaces[0]?.id||'';const space=parking(record.parkingSpaceId),history=assignmentsForSpace(record.parkingSpaceId),availableFrom=history.length?addDays(history.at(-1).end,1):today,candidate=data.contracts.find(c=>prop(c.propertyId)?.complexId===space?.complexId&&c.end>=availableFrom);if(!candidate){toast('No hay un contrato compatible disponible para asignar esta cochera.');editing=null;return;}record.contractId=candidate.id;record.start=candidate.start>availableFrom?candidate.start:availableFrom;record.end=candidate.end;}
  if(type==='payment'){if(record.paidAmount===undefined)record.paidAmount=record.paidDate?Number(record.amount)||0:0;if(opts.collect){record.paidAmount=Number(record.amount)||0;record.paidDate=today;}if(opts.presetKind)record.kind=opts.presetKind;if(opts.presetPeriod)record.period=opts.presetPeriod;}
  $('#dialogKicker').textContent=opts.collect?'COBRANZA':id?'EDITAR REGISTRO':'NUEVO REGISTRO';$('#dialogTitle').textContent=opts.collect?'Registrar pago':(id?'Editar ':'Nuevo ')+s.title.toLowerCase();$('#deleteRecord').hidden=!id||!!opts.collect||!isAdmin();
  $('#formFields').innerHTML=s.fields.map(([key,label,kind,required,wide])=>{const value=record[key]??({period:homeMonth,dueDate:today,paidAmount:0,paidDate:'',frequency:3,dueDay:10,deposit:0}[key]??'');let control;
    if(['complex','property','parkingSpace','tenant','contract','select'].includes(kind)){const optionHtml=kind==='select'?wide.map(x=>`<option value="${esc(x)}">${esc(x||'Sin especificar')}</option>`).join(''):optionsFor(kind,record);control=`<select name="${key}" ${required?'required':''}>${!required&&kind!=='select'?'<option value="">Seleccionar…</option>':''}${optionHtml}</select>`;}
    else control=`<input name="${key}" type="${kind}" value="${esc(value)}" ${required?'required':''} ${kind==='number'?'min="0" step="'+(key==='frequency'||key==='dueDay'||key==='bedrooms'?'1':'0.01')+'"':''} ${key==='frequency'?'max="60"':''} ${key==='dueDay'?'max="31" min="1"':''} />`;
    return `<div class="field ${wide==='wide'?'wide':''}"><label for="field-${key}">${esc(label)}</label>${control.replace(/(name="[^"]+")/,`$1 id="field-${key}"`)}</div>`;
  }).join('')+(type==='contract'?'<p class="form-note wide">El depósito es un importe registrado. Las cocheras se asignan por separado y pueden cambiar durante la vigencia.</p>':type==='parkingAssignment'?'<p class="form-note wide">La cochera y la unidad deben pertenecer al mismo complejo. El sistema bloquea fechas superpuestas para una misma cochera.</p>':type==='payment'?'<p class="form-note wide">Para un pago parcial, indicá el total cobrado acumulado. Cada incremento genera un comprobante inalterable asociado a tu usuario.</p>':'');
  for(const [key,,kind] of s.fields){if(kind==='select'||['complex','property','parkingSpace','tenant','contract'].includes(kind)){const el=$(`[name="${key}"]`);if(record[key]!==undefined)el.value=String(record[key]);}}
  $('#formDialog').showModal();
}
async function submitForm(e){e.preventDefault();if(!editing||busy)return;const {type,id}=editing,s=schema[type],form=new FormData(e.currentTarget),obj={};for(const [key,,kind] of s.fields){const value=form.get(key)??'';obj[key]=kind==='number'?Number(value||0):String(value).trim();}
  if(type==='contract'&&obj.end<obj.start){toast('La fecha de fin debe ser posterior al inicio.');return;}if(type==='contract'&&(!Number.isInteger(obj.frequency)||obj.frequency<1||obj.frequency>60)){toast('Ingresá una frecuencia de 1 a 60 meses.');return;}if(type==='contract'&&obj.lastAdjustmentDate&&obj.lastAdjustmentDate<obj.start){toast('El último ajuste no puede ser anterior al inicio.');return;}if(type==='contract'&&obj.lastAdjustmentDate&&obj.lastAdjustmentDate>today){toast('El último ajuste no puede estar en el futuro.');return;}if(type==='contract'&&obj.lastAdjustmentDate&&obj.lastAdjustmentDate>obj.end){toast('El último ajuste no puede ser posterior al fin del contrato.');return;}if(type==='payment'&&obj.paidAmount>obj.amount){toast('El monto cobrado no puede superar el monto total.');return;}if(type==='payment'&&obj.paidDate&&obj.paidDate>today){toast('La fecha cobrada no puede estar en el futuro.');return;}if(type==='payment'){if(obj.paidAmount>0&&!obj.paidDate)obj.paidDate=today;if(obj.paidAmount===0)obj.paidDate='';}if(type==='payment'&&data.payments.some(p=>p.id!==id&&p.contractId===obj.contractId&&p.kind===obj.kind&&p.period===obj.period)){toast('Ya existe ese concepto para este contrato y período. Editá el registro existente.');return;}
  if(type==='contract'&&data.contracts.some(c=>c.id!==id&&c.propertyId===obj.propertyId&&c.start<=obj.end&&obj.start<=c.end)){toast('Ya existe un contrato que se superpone para esta propiedad.');return;}
  if(type==='property'&&id&&data.properties.find(item=>item.id===id)?.complexId!==obj.complexId&&data.contracts.some(c=>c.propertyId===id&&data.parkingAssignments.some(a=>a.contractId===c.id))){toast('No se puede cambiar el complejo de una unidad con historial de cocheras.');return;}
  if(type==='parking'&&id&&parking(id)?.complexId!==obj.complexId&&data.parkingAssignments.some(a=>a.parkingSpaceId===id)){toast('No se puede cambiar el complejo de una cochera con historial de asignaciones.');return;}
  if(type==='contract'&&id&&data.contracts.find(item=>item.id===id)?.propertyId!==obj.propertyId&&data.parkingAssignments.some(a=>a.contractId===id)){toast('Revisá o finalizá primero las asignaciones de cochera de este contrato.');return;}
  if(type==='parkingAssignment'){const c=contract(obj.contractId),space=parking(obj.parkingSpaceId),unit=prop(c?.propertyId);if(obj.end<obj.start){toast('La fecha final de la cochera debe ser posterior al inicio.');return;}if(!c||!space||!unit||unit.complexId!==space.complexId){toast('La cochera y la unidad deben pertenecer al mismo complejo.');return;}if(obj.start<c.start||obj.end>c.end){toast('La asignación debe estar dentro de la vigencia del contrato.');return;}if(data.parkingAssignments.some(item=>item.id!==id&&item.parkingSpaceId===obj.parkingSpaceId&&item.start<=obj.end&&obj.start<=item.end)){toast('Esa cochera ya está asignada durante parte de las fechas elegidas.');return;}}
  const previous=type==='payment'&&id?data.payments.find(item=>item.id===id):null;
  const previousPaid=previous?collectedAmount(previous):0;
  if(type==='payment'&&obj.paidAmount<previousPaid){toast('Los pagos registrados no se reducen ni se borran. Cargá un ajuste administrativo por separado.');return;}
  busy=true;e.currentTarget.querySelector('[type="submit"]').disabled=true;
  try{
    const saved=await saveEntity(type,id,obj);
    if(type==='payment'&&obj.paidAmount>previousPaid){await addReceipt(id||saved?.id,obj.paidAmount-previousPaid,obj.paidDate||today);}
    $('#formDialog').close();editing=null;await reloadData();toast('Registro guardado y atribuido a tu usuario.');
  }catch(error){toast(cloudMessage(error));}
  finally{busy=false;e.currentTarget.querySelector('[type="submit"]').disabled=false;}
}
async function deleteEditing(){if(!editing?.id||busy)return;const {type,id}=editing;const linked=type==='complex'&&(data.properties.some(p=>p.complexId===id)||data.parkingSpaces.some(p=>p.complexId===id))||type==='property'&&data.contracts.some(c=>c.propertyId===id)||type==='parking'&&data.parkingAssignments.some(a=>a.parkingSpaceId===id)||type==='tenant'&&data.contracts.some(c=>c.tenantId===id)||type==='contract'&&(data.payments.some(p=>p.contractId===id)||data.adjustments.some(a=>a.contractId===id)||data.parkingAssignments.some(a=>a.contractId===id));if(linked){toast('Tiene registros vinculados. Conservá el historial o eliminá primero las relaciones.');return;}if(!confirm('¿Eliminar este registro? Esta acción quedará registrada.'))return;busy=true;try{await deleteEntity(type,id);$('#formDialog').close();editing=null;await reloadData();toast('Registro eliminado y asentado en la actividad.');}catch(error){toast(cloudMessage(error));}finally{busy=false;}}
async function applyAdjustment(){const c=contract($('#calcContract').value),rate=Number($('#calcRate').value),date=c&&nextAdjustment(c);if(!c||$('#calcRate').value===''||!Number.isFinite(rate)||rate<0||rate>1000||!date||busy)return;const after=adjustedRent(c.rent,rate);if(!confirm(`Aplicar ${rate}% al canon de ${propName(c)} con fecha ${dateLabel(date)}?\n${money(c.rent)} → ${money(after)}`))return;busy=true;try{await saveAdjustment(c.id,date,rate,Number(c.rent),after);$('#calcRate').value='';await reloadData();toast('Ajuste aplicado y registrado.');}catch(error){toast(cloudMessage(error));}finally{busy=false;}}
